model.en:
// Option 1 — capture the active context and re-enter it for the detached work
import { context, trace } from '@opentelemetry/api';

@Post('orders')
async create(@Body() dto: CreateOrderDto) {
  const order = await this.orders.save(dto);
  const active = context.active(); // the request's context, holding the current span
  // re-enter the captured context so the detached write still sees the request span as parent
  context.with(active, () => {
    void this.audit.writeAudit('order.created', order.id)
      .catch((err) => trace.getActiveSpan()?.recordException(err));
  });
  return order;
}

// Option 2 — simplest correct fix: just await it, so it stays inside the ALS chain
//   await this.audit.writeAudit('order.created', order.id);

Why: the current span lives in AsyncLocalStorage tied to the awaited call chain. An unawaited call drops out of that chain, so writeAudit runs with no active span and OTel opens a fresh root — the audit becomes its own trace. Awaiting keeps it inside the chain (the span nests, at the cost of latency). If you truly want it detached for speed, you must capture context.active() and re-enter it with context.with(...) so the detached continuation still parents to the request span. Either way the audit span ends up under the request trace, not orphaned.

model.ru:
// Вариант 1 — захвати активный контекст и переоткрой его для отсоединённой работы
import { context, trace } from '@opentelemetry/api';

@Post('orders')
async create(@Body() dto: CreateOrderDto) {
  const order = await this.orders.save(dto);
  const active = context.active(); // контекст запроса, держащий текущий span
  // переоткрываем захваченный контекст, чтобы отсоединённая запись видела span запроса как родителя
  context.with(active, () => {
    void this.audit.writeAudit('order.created', order.id)
      .catch((err) => trace.getActiveSpan()?.recordException(err));
  });
  return order;
}

// Вариант 2 — простейший верный фикс: просто отавайть, чтобы остаться внутри ALS-цепочки
//   await this.audit.writeAudit('order.created', order.id);

Почему: текущий span живёт в AsyncLocalStorage, привязанный к отавайченной цепочке вызовов. Неотавайченный вызов выпадает из этой цепочки, так что writeAudit выполняется без активного span и OTel открывает свежий корень — аудит становится своим трейсом. Await держит его внутри цепочки (span вкладывается, ценой латентности). Если ты действительно хочешь отсоединить ради скорости, ты обязан захватить context.active() и переоткрыть его через context.with(...), чтобы отсоединённое продолжение всё ещё имело родителем span запроса. В любом случае span аудита оказывается под трейсом запроса, а не осиротевшим.
